/// BUG 1: returns byte length of s, not word count
pub fn word_count(s: &str) -> usize {
    s.len()
}

/// BUG 2: counts only '.', not '!' or '?'
pub fn sentence_count(s: &str) -> usize {
    s.chars().filter(|&c| c == '.').count()
}

/// BUG 3: divides by count+1 instead of count
pub fn avg_word_length(s: &str) -> f64 {
    let words: Vec<&str> = s.split_whitespace().collect();
    let count = words.len();
    if count == 0 {
        return 0.0;
    }
    let total: usize = words.iter().map(|w| w.len()).sum();
    total as f64 / (count + 1) as f64
}

