use textstats::{word_count, sentence_count, avg_word_length};

#[test]
fn test_word_count() {
    assert_eq!(word_count("hello world"), 2);
}

#[test]
fn test_word_count_three() {
    assert_eq!(word_count("one two three"), 3);
}

#[test]
fn test_sentence_count() {
    assert_eq!(sentence_count("Hello! How are you? Good."), 3);
}

#[test]
fn test_avg_word_length() {
    let avg = avg_word_length("cat at");
    assert!((avg - 2.5).abs() < 1e-9, "expected 2.5 got {}", avg);
}
